INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_25b7acbec2d1c49d2176d8ed","wiki/sources/ril-408-48-inb-2026-data.md",11,"Seite 9","Rangieren; Allgemeines 408.4811\n\nSeite 2\n\n(1) Besonderheiten (z. B. gestÃ¶rte BahnÃ¼bergangssicherung, niedrigere Geschwindigkeit als 25 km/h) sind dem Tf von der in Absatz (3) a) genannten\n\nStelle bekanntzugeben.\n\nBesonderhei- (2) Besonderheiten dÃ¼rfen von der Bekanntgabe ausgenommen werden, wenn:\n\nten bekannt\n\n- Gleise mit abgeschalteter oder gestÃ¶rter Oberleitung mit Fahrleitungssignageben\n\nlen oder\n\n- Besonderheiten in Gleisen, z.B. durch WÃ¤rterhaltscheiben\n\ngekennzeichnet sind.\n\nZustÃ¤ndige (3) Es gilt Folgendes:\n\nStelle\n\na) Bevor der Tf in einen Ortsstellbereich hineinfÃ¤hrt, muss er sich bei der zustÃ¤ndigen Stelle melden oder Unterlagen einsehen. Die zustÃ¤ndige Stelle\n\nbzw. die Unterlagen werden in Ã¶rtlichen ZusÃ¤tzen genannt.\n\nb) Bei Arbeitsaufnahme oder nach einer Arbeitsunterbrechung in einem Ortsstellbereich muss sich der Tf bei der zustÃ¤ndigen Stelle melden oder Unterlagen einsehen (Ã¶rtliche ZusÃ¤tze). Die zustÃ¤ndige Stelle bzw. die Unterlagen werden in Ã¶rtlichen ZusÃ¤tzen genannt.\n\nUnregelmÃ¤- (4) Der Tf muss UnregelmÃ¤ÃŸigkeiten an Bahnanlagen und Fahrzeugen an die in\n\nÃŸigkeiten Ã¶rtlichen ZusÃ¤tzen genannte zustÃ¤ndige Stelle melden.\n\nZusÃ¤tzliche (5) In Ã¶rtlichen ZusÃ¤tzen kÃ¶nnen zusÃ¤tzliche Regeln gegeben sein, z.B. Be-\n\nRegeln schreibung des Ortsstellbereiches, dessen Grenzen und weitere Ã¶rtliche Regeln.\n\n5 Verhalten bei Gefahr oder UnregelmÃ¤ÃŸigkeiten\n\nGefahr (1) Wenn eine Gefahr droht, muss in eigener Verantwortung umsichtig und entschlossen alles getan werden, um die Gefahr abzuwenden oder zu mindern.\n\nBei Gefahr mÃ¼ssen Fahrzeuge angehalten werden, soweit nicht die Gefahr\n\ndurch das Anhalten vergrÃ¶ÃŸert wird. Eine Gefahr muss auch fÃ¼r Nachbargleise angenommen werden, wenn nicht einwandfrei festgestellt wird, dass die\n\nNachbargleise befahren werden kÃ¶nnen.",236,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb1934ca7c289e71ef25d41e31a2f0868c2b783e61\",\"page\":9,\"source_id\":\"src_4bb923a8606c9db71535\",\"source_sha256\":\"960465cf69d7a51f7111ff1f59c62b0b1d3ab5047870752d21a5be32b45450f9\",\"source_version_id\":\"sv_af0af799a8ddd3dbaa43afbe\"}","670d7cb84959ee9a1c8fd644dd6842782910449eef84a578a13455619fedd9b4"],["chunk_92f769c1ae4afc85165335d4","wiki/sources/ril-408-48-inb-2026-data.md",12,"Seite 9","(2) Bei UnregelmÃ¤ÃŸigkeiten an Bahnanlagen und Fahrzeugen sind folgende Regeln zu beachten:\n\nUnregelmÃ¤ÃŸig- a) Wird ein Mangel am Oberbau gemeldet oder festgestellt, mÃ¼ssen MaÃŸkeiten an nahmen bei Gefahr getroffen werden.\n\nBahnanlagen\n\n- Der Tf muss den Mangel dem Ww mitteilen.\n\n- Der Ww muss fÃ¼r das Sperren des Gleises sorgen.\n\nUnregelmÃ¤ÃŸig- b) Wenn an Fahrzeugen oder Ladungen UnregelmÃ¤ÃŸigkeiten (z. B. Brandgekeiten an ruch, Ã–lqualm, Flammen, rot glÃ¼hende Radsatzlager, PfeiftÃ¶ne, blockierter\n\nFahrzeugen Radsatz, Funken am Radsatz, kreischendes GerÃ¤usch, rot glÃ¼hende\n\nBremsklÃ¶tze oder Radreifen, brennende BremsbelÃ¤ge, unruhiger Lauf des\n\nFahrzeugs, klapperndes klirrendes GerÃ¤usch, regelmÃ¤ÃŸiges starkes Klopfen oder Schlagen, lose Wagendecken, verschobene Ladung, nach auÃŸen\n\naufschlagende TÃ¼ren, UnregelmÃ¤ÃŸigkeiten an Stromabnehmern, Feuer)\n\nfestgestellt oder solche UnregelmÃ¤ÃŸigkeiten gemeldet werden, mÃ¼ssen\n\nMaÃŸnahmen bei Gefahr getroffen werden.\n\nNach dem Anhalten muss der Tf die UnregelmÃ¤ÃŸigkeit dem Ww mitteilen.\n\nGÃ¼ltig ab: 14.12.2025",134,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb1934ca7c289e71ef25d41e31a2f