INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_2dcef9715e784a5b437f877b","wiki/sources/ril-408-48-inb-2026-data.md",71,"Seite 45","DB InfraGO AG\n\nEisenbahnbetriebsverfahren Bahnbetrieb\n\nDB InfraGO AG | I.IBB 31 Adam-Riese-StraÃŸe 11-13\n\nAdam-Riese-StraÃŸe 11-13 | 60327 Frankfurt am Main 60327 Frankfurt am Main\n\nwww.dbinfrago.com\n\n05.12.2024\n\nNeuherausgabe Richtlinienfamilie 408 - Fahrdienstvorschrift; Richtliniengruppe 408.48\n\nSehr geehrte Damen und Herren,\n\ndie Neuherausgabe zu den Richtlinien 408.48 gilt ab 14.12.2025.\n\nSie enthÃ¤lt folgende Richtlinien und dazugehÃ¶rige AnhÃ¤nge sowie ZusÃ¤tze:\n\n408.4801 408.4812 408.4818\n\n408.4801A01 408.4813 408.4821\n\n408.4801A02 408.4814 408.4831\n\n408.4802 408.4815 408.4841\n\n408.4811 408.4816 408.4851\n\n408.4811Z31 408.4817\n\nÃœbergang der GÃ¼ltigkeit\n\nDie bisherigen Richtlinien 408.48 sowie die ZusÃ¤tze 31 werden mit Ablauf des 13.12.2025\n\nungÃ¼ltig und sind wegzulegen.\n\nDB InfraGO AG | Sitz: Frankfurt am Main | Registergericht: Frankfurt am Main\n\nHRB 50879 | USt-IdNr.: DE 199861757 | Vorsitz des Aufsichtsrats: Berthold Huber\n\nVorstand: Dr. Philipp Nagl (Vorsitz), Jens Bergmann, Ingrid Felipe, Dr. Christian GruÃŸ, Heike Junge-Latz, Heinz\n\nSiegmund, Ralf Thieme\n\nNÃ¤here Informationen zur Datenverarbeitung der DB InfraGO AG finden Sie hier: www.dbinfrago.com/datenschutz\n\nSeite 1 von 4",152,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb1934ca7c289e71ef25d41e31a2f0868c2b783e61\",\"page\":45,\"source_id\":\"src_4bb923a8606c9db71535\",\"source_sha256\":\"960465cf69d7a51f7111ff1f59c62b0b1d3ab5047870752d21a5be32b45450f9\",\"source_version_id\":\"sv_af0af799a8ddd3dbaa43afbe\"}","5958aff5d50f378369d081981e64f42045ea4daa32238538ebff57f3d62c1568"],["chunk_0132b7156b760396c9e05bb0","wiki/sources/ril-408-48-inb-2026-data.md",72,"Seite 46","ErlÃ¤uterungen\n\nKennzeichnung von inhaltlichen Ã„nderungen\n\nIn den Richtlinien sind Zeilen mit inhaltlichen TextÃ¤nderungen am Rand durch â€ž*â€œ\n\ngekennzeichnet. Bei entfallenen Texten ist das Sternchen neben die letzte nicht geÃ¤nderte Zeile\n\ngesetzt. Nicht gekennzeichnet ist die geÃ¤nderte Leseransprache.\n\nLeseransprache\n\nFÃ¼r die Leseransprache der handelnden Personen, werden neu nur noch die AbkÃ¼rzungen\n\nâ€žWwâ€œ (WeichenwÃ¤rter), â€žTfâ€œ (TriebfahrzeugfÃ¼hrer), â€žRbâ€œ (Rangierbegleiter) und â€žFdlâ€œ\n\n(Fahrdienstleiter) verwendet.\n\nAllgemein\n\nDas â€žBetriebsstellenbuchâ€œ wird neu als â€žStreckenbuch EIUâ€œ umbenannt. Die betriebliche\n\nUnterlage â€žAngaben fÃ¼r das Streckenbuchâ€œ wird neu als â€žAngaben fÃ¼r das Streckenbuch EVUâ€œ\n\numbenannt. Grundlage hierfÃ¼r sind die Vorgaben der TSI OPE. Auf diese Ã„nderungen wird in\n\nden folgenden ErlÃ¤uterungstexten zu den jeweils betroffenen Richtlinien nicht mehr\n\nhingewiesen.\n\nWenn in einer Richtlinie ein Verweis auf eine andere Richtlinie der Richtlinienfamilie 408\n\nenthalten war, wird diesem Verweis die Kurzbezeichnung â€žRilâ€œ vorangestellt. Verweise denen\n\nnoch â€žModulâ€œ vorangestellt war, werden durch â€žRilâ€œ ersetzt. Wenn die Rede vom Plural\n\nâ€žRichtlinienâ€œ ist, wird â€žRichtlinienâ€œ ausgeschrieben. Gleiches gilt fÃ¼r Verweise auf andere\n\nRichtlinien.\n\nSeite 2 von 4",162,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb1934ca7c289e71ef25d41e31a2f0868c2b783e61\",\"page\":46,\"source_id\":\"src_4bb923a8606c9db71535\",\"source_sha256\":\"960465cf69d7a51f7111ff1f59c62b0b1d3ab5047870752d21a5be32b45450f9\",\"source_version_id\":\"sv_af0af799a8ddd3dbaa43afbe\"}","9cbfa368615dbcc98653cda068cecce02ef4d8c239447157ef3fd936fe94f4ff"],["chunk_cf84d80aa44c70e1bb57630a","wiki/sources/ril-408-48-inb-2026-data.md",73,"Seite 47","Ril 408.4801 â€“ ZusÃ¤tzliche oder abweichende Regeln\n\nneu: Richtlinie, Abschnitt, Absatz usw. alt: Richtlinie, Abschnitt, Absatz usw.\n\nTitel: ZÃ¼ge fahren; ZusÃ¤tzliche oder Titel: ZÃ¼ge fahren; Inhalt und zusÃ¤tzliche\n\nabweichende Regeln Regeln\n\n408.0051 408.4801 1\n\n408.4801 1 408.4801 2\n\n408.4801 2 408.4801 3\n\nDer Titel wurde aufgrund der Ãœbernahme des Abschnitts 1 in die Ril 408.0051 angepasst.\n\nIn Abschnitt 2 wurde der Begriff â€žInfrastrukturbetreiberâ€œ durch â€žEisenbahninfrastrukturunternehmen (EIU)â€œ ersetzt.\n\nAnhang 408.4801A01â€“ Verkehrstage\n\nDer bisherige Anhang 408.4801A01 â€žBegriffeâ€œ wurde aufgelÃ¶st und in die Grundsatzrichtlinie\n\n408.0055 Ã¼berfÃ¼hrt. Daher wurde die Nummerierung des bisherigen Anhanges 408.4801A03 in\n\nAnhang 408.4801A01 geÃ¤ndert.\n\nIn Abschnitt 1 wurde die Tabelle â€žWeitere Feiertageâ€œ gestrichen, da Feiertage aus den\n\nInformations- und Nachrichtenmedien ersichtlich sind.\n\nAnhang 408.4801A02 â€“ GÃ¼tigkeit der Richtlinien fÃ¼r Mitarbeiter\n\nDer bisherige Anhang 408.4801A02 â€žAbkÃ¼rzungenâ€œ wurde aufgelÃ¶st und in die\n\nGrundsatzrichtlinie 408.0054 Ã¼berfÃ¼hrt. Daher wurde die Nummerierung des bisherigen\n\nAnhanges 408.4801A04 in Anhang 408.4801A02 geÃ¤ndert.\n\nIn der Tabelle wurden die Richtlinien 408.0051, 408.0054, 408.0055 und 408.0056 neu\n\naufgenommen.\n\n408.4802 â€“ TÃ¤tigkeiten, Uhrzeitvergleich\n\nIm Abschnitt 6 Absatz (1) wurde festgelegt, dass aufgrund der besseren Nachvollziehbarkeit die\n\nMitarbeiter neben ihrer Unterschrift auch ihren Namen in Druckbuchstaben vermerken mÃ¼ssen.\n\n408.4811 - Allgemeines\n\nIn Abschnitt 6 Absatz (2) wurde der Verweis auf die Richtlinie 408.0054 geÃ¤ndert.\n\n408.4812 - Besonderheiten\n\nAbschnitt 2 Absatz (1)\n\nLesen Sie die ErlÃ¤uterungen zu den geÃ¤nderten Regeln in den Richtlinien 408.0435 und\n\n408.2435 jeweils im Abschnitt 1 Absatz (3).",230,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb1934ca7c289e71ef25d41e31a2f0868c2b783e61\",\"page\":47,\"source_id\":\"src_4bb923a8606c9db71535\",\"source_sha256\":\"960465cf69d7a51f7111ff1f59c62b0b1d3ab5047870752d21a5be32b45450f9\",\"source_version_id\":\"sv_af0af799a8ddd3dbaa43afbe\"}","7b48404a06dcda277256b4efe01168d79f723d2a1c87b70f5d150094155a1176"],["chunk_07262c75074a5afd164f488e","wiki/sources/ril-408-48-inb-2026-data.md",74,"Seite 47","Seite 3 von 4",4,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb1934ca7c289e71ef25d41e31a2f0868c2b783e61\",\"page\":47,\"source_id\":\"src_4bb923a8606c9db71535\",\"source_sha256\":\"960465cf69d7a51f7111ff1f59c62b0b1d3ab5047870752d21a5be32b45450f9\",\"source_version_id\":\"sv_af0af799a8ddd3dbaa43afbe\"}","46ae215b7d73d35e8a0a87c31eac2ea10f0927a974019bf75f67a90338bb6d0f"],["chunk_d532bde612867b2899f970b0","wiki/sources/ril-408-48-inb-2026-data.md",75,"Seite 48","408.4813 - Vorbereiten\n\nAbschnitt 1 Absatz (1) a) Nr. 1\n\nLesen Sie die ErlÃ¤uterungen zu den geÃ¤nderten Regeln in den Richtlinien 408.0435 und\n\n408.2435 jeweils im Abschnitt 1 Absatz (3).\n\n408.4841 - Hauptgleise\n\nAbschnitt 3\n\nIn der bisherigen Regel in Absatz (4) wurde die Nummer des Befehls geÃ¤ndert. Lesen hierzu\n\ndie ErlÃ¤uterungen zu den geÃ¤nderten Regeln in den Richtlinien 408.0411 bzw. 408.2411.\n\nAbschnitt 10\n\nDie AbschnittsÃ¼berschrift wurde durch eine ErgÃ¤nzung des Begriffs â€žBetriebsart SHâ€œ in â€žETCS-\n\nBetriebsart SHâ€œ prÃ¤zisiert.\n\n408.4851 â€“ Gleise sperren, Oberleitung ausgeschaltet oder gestÃ¶rt\n\nAbschnitt 3\n\nDie Regeln in Abschnitt 3 Absatz (3) a) wurden ergÃ¤nzt und gelten somit auch fÃ¼r\n\nelektromechanische Stellwerke.\n\nMit freundlichen GrÃ¼ÃŸen\n\nDB InfraGO AG, GeschÃ¤ftsbereich Fahrweg\n\ngez. Christian Ehrhardt gez. Julian Huth\n\nLeiter Grundlagen und Verfahren Experte Fahrdienstvorschrift\n\nBahnbetrieb\n\nSeite 4 von 4",131,"{\"canonical_url\":null,\"normalized_sha256\":\"10aa66d160633cc7abad13eb19