INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_4c7515b0f3bcdfe6534b4952","wiki/sources/ril-420-02-inb-2026-data.md",29,"Seite 20","Bahnbetrieb Betriebsleitstellen\n\nZusammenarbeit mit Eisenbahnverkehrsunternehmen 420.0200A01\n\nStÃ¶rungsmanagement Betriebsleitstellen DB InfraGO AG Seite 3\n\nHinweis:\n\n* Die Lagebeobachtung der BZ/NLZ entbindet die EVU nicht\n\n* von der eigenen Beobachtung.\n\n(3) Stufe 0 â€“ MaÃŸnahmen zur Vorbereitung Stufe 0\n\n*\n\nBei Anzeichen, welche auf die Entwicklung einer grÃ¶ÃŸeren\n\ninfrastrukturbezogenen StÃ¶rung hindeuten, z.B.\n\n- Unwetterwarnungen,\n\n- Hochwasservorhersagen,\n\n- Verdacht auf organisierte Fremdeinwirkung,\n\n- Pandemien,\n\n- Sonstige drohende EinschrÃ¤nkungen der Infra-\n\n* struktur der DB InfraGO AG.\n\nBei regionaler Betroffenheit wird die Stufe 0 durch die ent- Ausrufung der\n\nsprechende Region (Betriebszentrale) in Absprache mit der Stufe 0\n\nNetzleitzentrale ausgerufen.\n\nBei zu erwartender Ã¼berregionaler Betroffenheit wird die\n\nStufe 0 durch die Netzleitzentrale in Absprache mit den betroffenen Regionen ausgerufen.\n\nDie Stufe 0 ist rechtzeitig anzukÃ¼ndigen. Dies bedeutet, AnkÃ¼ndigung\n\ndass der Eintritt zu einem definierten Zeitpunkt erfolgt (z.B. der Stufe 0\n\nam Folgetag zu einer bestimmten Uhrzeit). Ziel ist die volle\n\nEinsatzbereitschaft der Betroffenen zum Eintritt der Stufe 0.\n\nDie Geltungsdauer der Stufe 0 ist mÃ¶glichst bei Ausrufung Geltungsdauer\n\ndieser zeitlich zu begrenzen. Sollte dies nicht mÃ¶glich sein, der Stufe 0\n\nmuss die Stufe 0 nach Wegfall des Anlasses durch den\n\nAusrufenden zeitnah aufgehoben werden.\n\nAus den durch die fortwÃ¤hrende Lagebeobachtung gewon- 